DROP POLICY IF EXISTS "telehealth_screen_shares_hospital_read" ON public.telehealth_screen_shares; CREATE POLICY "telehealth_screen_shares_hospital_read" ON public.telehealth_screen_shares FOR SELECT USING ( EXISTS ( SELECT 1 FROM public.telehealth_sessions s JOIN public.profiles p ON p.id = auth.uid() WHERE s.id = telehealth_screen_shares.telehealth_session_id AND s.hospital_id = p.hospital_id AND ( p.id = s.host_id OR p.id = telehealth_screen_shares.initiated_by OR EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'admin' AND ur.hospital_id = s.hospital_id ) ) ) ); GRANT SELECT ON public.telehealth_screen_shares TO authenticated; GRANT ALL ON public.telehealth_screen_shares TO service_role;